import{_ as o,o as a,c as r,au as n,aJ as t,aK as s,aL as i}from"./chunks/framework.BKE8ybUb.js";import"./chunks/theme.XLLNTsgn.js";const _=JSON.parse('{"title":"Bloom","description":"","frontmatter":{"outline":[1,2],"prev":{"text":"Elemental Reactions","link":"/guide/elements/Elemental_Reactions"}},"headers":[],"relativePath":"Bloom.md","filePath":"wiki/elemental_reactions/Bloom.md","lastUpdated":1783267680000}'),l={name:"Bloom.md"};function d(p,e,c,h,g,m){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="Bloom" tabindex="-1">Bloom <a class="header-anchor" href="#Bloom" aria-label="Permalink to “Bloom”">​</a></h1><p>Bloom is the <a href="./guide/elements/Elemental_Reactions">Elemental Reaction</a> triggered when <span class="dendro"><strong>Dendro</strong></span> is applied onto an entity already affected by <span class="hydro"><strong>Hydro</strong></span> or vice versa.</p><p>This reaction produces a Dendro Core, which stays on the field for up to 6 seconds. Only 5 Dendro Cores can exist at a time in a <strong>64m</strong> radius, and producing more than 5 Dendro Cores will cause the oldest one to explode immediately.</p><h2 id="Dendro_Core" tabindex="-1">Dendro Core <a class="header-anchor" href="#Dendro_Core" aria-label="Permalink to “Dendro Core”">​</a></h2><p>Once a Dendro Core&#39;s duration expires, it explodes, dealing <span class="dendro"><strong>AoE Dendro DMG</strong></span> in a <strong>5m</strong> radius to all entities.</p><div align="center"><video width="95%" height="auto" controls><source src="'+t+'" type="video/mp4"> Your browser does not support the video tag. </video></div><p>When it receives <span class="pyro"><strong>Pyro DMG</strong></span> or <span class="electro"><strong>Electro DMG</strong></span>, the <a href="#Hyperbloom">Hyperbloom</a> and <a href="#Burgeon">Burgeon</a> Elemental Reactions can be triggered on the Dendro Core.</p><p>DMG dealt to the &quot;owners&quot; of all Bloom-related reactions will always be <strong>2%</strong> of the original DMG dealt.</p><p>An entity is considered to have &quot;owned&quot; the core if they triggered:</p><ul><li>the <a href="#Bloom">Bloom</a> reaction responsible for the Dendro Core or,</li><li>the secondary <a href="#Hyperbloom">Hyperbloom</a>/<a href="#Burgeon">Burgeon</a> reaction.</li></ul><p>A Dendro Core may have multiple entities as its owner, but its DMG will be attributed to the most recent owner.</p><h3 id="Internal_Data" tabindex="-1">Internal Data <a class="header-anchor" href="#Internal_Data" aria-label="Permalink to “Internal Data”">​</a></h3><p>Reaction Multiplier: <strong>2</strong><br> Reaction ID(s):</p><ul><li><code>seven-elements:bloom_dendro</code> (triggered if <span class="dendro"><strong>Dendro</strong></span> was applied on a <span class="hydro"><strong>Hydro</strong></span> aura)</li><li><code>seven-elements:bloom_hydro</code> (triggered if <span class="hydro"><strong>Hydro</strong></span> was applied on a <span class="dendro"><strong>Dendro</strong></span> aura)</li><li><code>seven-elements:bloom_quicken</code> (triggered if <span class="hydro"><strong>Hydro</strong></span> was applied on a <span class="quicken"><strong>Quicken</strong></span> aura)</li></ul><div><br></div><hr><h1 id="Hyperbloom" tabindex="-1">Hyperbloom <a class="header-anchor" href="#Hyperbloom" aria-label="Permalink to “Hyperbloom”">​</a></h1><p><sup>    &lt; <a href="./guide/elements/Elemental_Reactions">Elemental Reactions</a></sup></p><p>Hyperbloom is the <a href="./guide/elements/Elemental_Reactions">Elemental Reaction</a> triggered on a <a href="#Dendro_Core">Dendro Core</a> when it receives <span class="electro"><strong>Electro DMG</strong></span>.</p><p>This reaction transforms the Dendro Core into a Sprawling Shot that homes in on the closest enemy within a <strong>24m</strong> radius, dealing increased <span class="dendro"><strong>AoE Dendro DMG</strong></span> in a <strong>1m</strong> radius. If no enemy can be found, it shoots up and disappears shortly after.</p><div align="center"><video width="95%" height="auto" controls><source src="'+s+'" type="video/mp4"> Your browser does not support the video tag. </video></div><h3 id="Internal_Data-1" tabindex="-1">Internal Data <a class="header-anchor" href="#Internal_Data-1" aria-label="Permalink to “Internal Data”">​</a></h3><p>Reaction Multiplier: <strong>3</strong><br> Reaction ID: <code>seven-elements:hyperbloom</code></p><div><br></div><hr><h1 id="Burgeon" tabindex="-1">Burgeon <a class="header-anchor" href="#Burgeon" aria-label="Permalink to “Burgeon”">​</a></h1><p><sup>    &lt; <a href="./guide/elements/Elemental_Reactions">Elemental Reactions</a></sup></p><p>Burgeon is the <a href="./guide/elements/Elemental_Reactions">Elemental Reaction</a> triggered on a <a href="#Dendro_Core">Dendro Core</a> when it receives <span class="pyro"><strong>Pyro DMG</strong></span>.</p><p>This reaction prematurely explodes the Dendro Core, dealing increased <span class="dendro"><strong>AoE Dendro DMG</strong></span> in a <strong>5m</strong> radius.</p><div align="center"><video width="95%" height="auto" controls><source src="'+i+'" type="video/mp4"> Your browser does not support the video tag. </video></div><h3 id="Internal_Data-2" tabindex="-1">Internal Data <a class="header-anchor" href="#Internal_Data-2" aria-label="Permalink to “Internal Data”">​</a></h3><p>Reaction Multiplier: <strong>3</strong><br> Reaction ID: <code>seven-elements:burgeon</code></p>',32)])])}const b=o(l,[["render",d]]);export{_ as __pageData,b as default};
